using Avalonia;
using Avalonia.Controls;
using Avalonia.Data;
using Avalonia.Layout;
using OfficeIMO.Project;
using System.Globalization;
using System.Net;
using System.Text;

namespace ProjectDesk;

public enum ProjectReportKind { ProjectOverview, CostOverview, WorkOverview }

/// <summary>Read-only reports on stored data. Resource totals and task totals are separate populations.</summary>
public sealed class ProjectReportsModule : UserControl {
    private readonly TabControl _tabs=new();
    private readonly TextBlock _title=new(){FontSize=22,FontWeight=Avalonia.Media.FontWeight.SemiBold};
    private readonly StackPanel _overview=new(){Spacing=18,Margin=new Thickness(20)};
    private readonly StackPanel _cost=new(){Spacing=18,Margin=new Thickness(20)};
    private readonly StackPanel _work=new(){Spacing=18,Margin=new Thickness(20)};
    public int LeafTaskCount {get;private set;}
    public ProjectReportKind SelectedReport {get=>(ProjectReportKind)_tabs.SelectedIndex;set=>_tabs.SelectedIndex=(int)value;}
    private const string Notice="Reports use stored values. Calculate Project to update supported schedules; imported totals may be stale. Only non-summary tasks are counted in task totals. Resource totals are shown separately and are never added to task totals. Missing values are reported, not assumed to be zero. No currency conversion is applied.";
    public ProjectReportsModule(){var root=new DockPanel();var header=new StackPanel{Margin=new Thickness(20,12),Spacing=8};header.Children.Add(_title);header.Children.Add(new TextBlock{Text=Notice,TextWrapping=Avalonia.Media.TextWrapping.Wrap,Foreground=DesignTokens.Secondary});DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
        _tabs.ItemsSource=new[]{Tab("Project Overview",_overview),Tab("Cost Overview",_cost),Tab("Work Overview",_work)};_tabs.SelectedIndex=0;root.Children.Add(_tabs);Content=root;}
    private static TabItem Tab(string title,Control content)=>new(){Header=title,Content=new ScrollViewer{Content=content}};
    public void Refresh(ProjectSession session){var snapshot=ReportSnapshot.Create(session);LeafTaskCount=snapshot.Tasks.Length;_title.Text=snapshot.Name;
        _overview.Children.Clear();_cost.Children.Clear();_work.Children.Clear();
        _overview.Children.Add(Cards(("Leaf tasks",snapshot.Tasks.Length.ToString()),("Summary tasks",snapshot.SummaryCount.ToString()),("Resources",snapshot.Resources.Length.ToString()),("Project dates",Dates(snapshot.Start,snapshot.Finish))));
        _overview.Children.Add(new TextBlock{Text="Task progress",FontSize=17,FontWeight=Avalonia.Media.FontWeight.SemiBold});
        _overview.Children.Add(Cards(("Complete",snapshot.Tasks.Count(t=>t.PercentComplete>=100).ToString()),("In progress",snapshot.Tasks.Count(t=>t.PercentComplete>0&&t.PercentComplete<100).ToString()),("Not started",snapshot.Tasks.Count(t=>t.PercentComplete==0).ToString()),("Progress absent",snapshot.Tasks.Count(t=>!t.PercentComplete.HasValue).ToString())));
        _overview.Children.Add(new TextBlock{Text="Stored task schedule",FontSize=17});
        _overview.Children.Add(Table(snapshot.Tasks.Select(t=>new OverviewRow(t)).ToArray(),("ID","Id",60),("Task","Name",300),("Start","Start",110),("Finish","Finish",110),("% Complete","Progress",100),("Critical","Critical",85),("Active","Active",85)));
        _cost.Children.Add(Cards(("Task cost",Total(snapshot.Tasks.Select(t=>t.Cost))), ("Actual cost",Total(snapshot.Tasks.Select(t=>t.ActualCost))), ("Remaining cost",Total(snapshot.Tasks.Select(t=>t.RemainingCost))), ("Baseline cost",Total(snapshot.Tasks.Select(t=>t.Baselines.FirstOrDefault(b=>(b.Number??0)==0)?.Cost)))));
        _cost.Children.Add(new TextBlock{Text="Task costs — highest stored cost first",FontSize=17});
        _cost.Children.Add(Table(snapshot.Tasks.OrderByDescending(t=>t.Cost).Select(t=>new CostRow(t)).ToArray(),("ID","Id",60),("Task","Name",300),("Cost","Cost",115),("Actual Cost","Actual",115),("Remaining Cost","Remaining",125),("Baseline Cost","Baseline",125),("Cost Variance","Variance",125)));
        _cost.Children.Add(new TextBlock{Text="Separate stored resource costs",FontSize=17});
        _cost.Children.Add(Table(snapshot.Resources.Select(r=>new ResourceRow(r)).ToArray(),("Resource","Name",300),("Cost","Cost",115),("Actual Cost","ActualCost",115),("Remaining Cost","RemainingCost",125)));
        _work.Children.Add(Cards(("Task work",Total(snapshot.Tasks.Select(t=>t.Work?.Minutes),true)), ("Actual work",Total(snapshot.Tasks.Select(t=>t.ActualWork?.Minutes),true)), ("Remaining work",Total(snapshot.Tasks.Select(t=>t.RemainingWork?.Minutes),true)), ("Baseline work",Total(snapshot.Tasks.Select(t=>t.Baselines.FirstOrDefault(b=>(b.Number??0)==0)?.Work?.Minutes),true))));
        _work.Children.Add(new TextBlock{Text="Task work — highest stored work first",FontSize=17});
        _work.Children.Add(Table(snapshot.Tasks.OrderByDescending(t=>t.Work?.Minutes).Select(t=>new WorkRow(t)).ToArray(),("ID","Id",60),("Task","Name",300),("Work","Work",115),("Actual Work","Actual",115),("Remaining Work","Remaining",125),("Baseline Work","Baseline",125),("Work Variance","Variance",125)));
        _work.Children.Add(new TextBlock{Text="Separate stored resource work",FontSize=17});
        _work.Children.Add(Table(snapshot.Resources.Where(r=>r.Type==null||r.Type==ProjectResourceType.Work).Select(r=>new ResourceRow(r)).ToArray(),("Resource","Name",300),("Type","Type",100),("Work","Work",115),("Actual Work","Actual",115),("Remaining Work","Remaining",125)));
    }
    private static Control Cards(params (string Label,string Value)[] cards){var panel=new WrapPanel{Orientation=Orientation.Horizontal};foreach(var card in cards){var inner=new StackPanel{Spacing=8};inner.Children.Add(new TextBlock{Text=card.Label,Foreground=DesignTokens.Secondary});inner.Children.Add(new TextBlock{Text=card.Value,FontSize=20,TextWrapping=Avalonia.Media.TextWrapping.Wrap});panel.Children.Add(new Border{Child=inner,Background=DesignTokens.Surface,BorderBrush=DesignTokens.Separator,BorderThickness=new Thickness(1),CornerRadius=DesignTokens.Radius,Padding=new Thickness(14),Margin=new Thickness(0,0,12,10),Width=245,MinHeight=92});}return panel;}
    private static DataGrid Table(object rows,params (string Title,string Property,double Width)[] columns){var grid=new DataGrid{AutoGenerateColumns=false,IsReadOnly=true,CanUserResizeColumns=true,CanUserReorderColumns=true,GridLinesVisibility=DataGridGridLinesVisibility.All,RowHeight=26,ColumnHeaderHeight=32,Height=340,ItemsSource=(System.Collections.IEnumerable)rows,FontSize=12};foreach(var column in columns)grid.Columns.Add(new DataGridTextColumn{Header=column.Title,Binding=new Binding(column.Property),Width=new DataGridLength(column.Width)});return grid;}
    private static string Number(decimal? value,bool work=false)=>value.HasValue?(work?value.Value/60:value.Value).ToString("N2",CultureInfo.InvariantCulture)+(work?" h":""):"—";
    private static string Total(IEnumerable<decimal?> values,bool work=false){var data=values.ToArray();int missing=data.Count(v=>!v.HasValue);var known=data.Where(v=>v.HasValue).Select(v=>v!.Value).ToArray();return (known.Length==0?"—":Number(known.Sum(),work))+(missing>0?$" ({missing} absent)":"");}
    private static string Dates(DateTime? start,DateTime? finish)=>(TaskColumns.Format(start)??"—")+" → "+(TaskColumns.Format(finish)??"—");
    private sealed record ReportSnapshot(string Name,ProjectTask[] Tasks,ProjectResource[] Resources,int SummaryCount,DateTime? Start,DateTime? Finish){public static ReportSnapshot Create(ProjectSession session){var all=session.Tasks;var dated=all.Where(t=>t.Start.HasValue&&t.Finish.HasValue).ToArray();return new(session.Document?.Name??"Project Overview",all.Where(t=>!t.IsSummary).ToArray(),session.Resources.ToArray(),all.Count(t=>t.IsSummary),dated.Length==0?null:dated.Min(t=>t.Start),dated.Length==0?null:dated.Max(t=>t.Finish));}}
    public sealed record OverviewRow {public string Id{get;}public string? Name{get;}public string? Start{get;}public string? Finish{get;}public string Progress{get;}public string Critical{get;}public string Active{get;}public OverviewRow(ProjectTask t){Id=(t.DisplayId??t.Uid).ToString();Name=t.Name;Start=TaskColumns.Format(t.Start);Finish=TaskColumns.Format(t.Finish);Progress=t.PercentComplete.HasValue?$"{t.PercentComplete}%":"—";Critical=TaskColumns.Format(t.IsCritical)??"—";Active=TaskColumns.Format(t.IsActive)??"—";}}
    public sealed record CostRow {public string Id{get;}public string? Name{get;}public string Cost{get;}public string Actual{get;}public string Remaining{get;}public string Baseline{get;}public string Variance{get;}public CostRow(ProjectTask t){Id=(t.DisplayId??t.Uid).ToString();Name=t.Name;var baseline=t.Baselines.FirstOrDefault(b=>(b.Number??0)==0)?.Cost;Cost=Number(t.Cost);Actual=Number(t.ActualCost);Remaining=Number(t.RemainingCost);Baseline=Number(baseline);Variance=Number(t.Cost-baseline);}}
    public sealed record WorkRow {public string Id{get;}public string? Name{get;}public string Work{get;}public string Actual{get;}public string Remaining{get;}public string Baseline{get;}public string Variance{get;}public WorkRow(ProjectTask t){Id=(t.DisplayId??t.Uid).ToString();Name=t.Name;var baseline=t.Baselines.FirstOrDefault(b=>(b.Number??0)==0)?.Work?.Minutes;Work=Number(t.Work?.Minutes,true);Actual=Number(t.ActualWork?.Minutes,true);Remaining=Number(t.RemainingWork?.Minutes,true);Baseline=Number(baseline,true);Variance=Number(t.Work?.Minutes-baseline,true);}}
    public sealed record ResourceRow {public string? Name{get;}public string Type{get;}public string Work{get;}public string Actual{get;}public string Remaining{get;}public string Cost{get;}public string ActualCost{get;}public string RemainingCost{get;}public ResourceRow(ProjectResource r){Name=r.Name;Type=TaskColumns.Format(r.Type)??"—";bool labor=r.Type==null||r.Type==ProjectResourceType.Work;Work=labor?Number(r.Work?.Minutes,true):"Not labor work";Actual=labor?Number(r.ActualWork?.Minutes,true):"—";Remaining=labor?Number(r.RemainingWork?.Minutes,true):"—";Cost=Number(r.Cost);ActualCost=Number(r.ActualCost);RemainingCost=Number(r.RemainingCost);}}
    public string ToHtml(ProjectSession session){var snapshot=ReportSnapshot.Create(session);var html=new StringBuilder("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>");html.Append(E(snapshot.Name));html.Append("</title><style>body{font:14px system-ui,sans-serif;color:#1d1d1f;background:#f5f5f7;margin:32px}h1{font-size:28px}h2{margin-top:32px}table{border-collapse:collapse;background:white;width:100%;margin-top:14px}th,td{border:1px solid #dcdce1;text-align:left;padding:8px;vertical-align:top}th{background:#ececf0}p{max-width:1100px;line-height:1.5}.notes{white-space:pre-wrap}@media print{body{background:white;margin:12px}tr{break-inside:avoid}}</style></head><body><h1>");html.Append(E(snapshot.Name));html.Append("</h1><p>").Append(E(Notice)).Append("</p><h2>Project Overview</h2><p>").Append(E($"{snapshot.Tasks.Length} leaf tasks · {snapshot.SummaryCount} summary tasks · {snapshot.Resources.Length} resources · {Dates(snapshot.Start,snapshot.Finish)}")).Append("</p><p>").Append(E($"Complete: {snapshot.Tasks.Count(t=>t.PercentComplete>=100)} · In progress: {snapshot.Tasks.Count(t=>t.PercentComplete>0&&t.PercentComplete<100)} · Not started: {snapshot.Tasks.Count(t=>t.PercentComplete==0)} · Progress absent: {snapshot.Tasks.Count(t=>!t.PercentComplete.HasValue)}")).Append("</p>");
        HtmlTable(html,["ID","Task","Start","Finish","% Complete","Critical","Active"],snapshot.Tasks.Select(t=>{var row=new OverviewRow(t);return new[]{row.Id,row.Name,row.Start,row.Finish,row.Progress,row.Critical,row.Active};}));
        html.Append("<h2>Cost Overview</h2><p>").Append(E($"Task cost: {Total(snapshot.Tasks.Select(t=>t.Cost))} · Actual cost: {Total(snapshot.Tasks.Select(t=>t.ActualCost))} · Remaining cost: {Total(snapshot.Tasks.Select(t=>t.RemainingCost))}")).Append("</p>");HtmlTable(html,["ID","Task","Cost","Actual Cost","Remaining Cost","Baseline Cost","Cost Variance"],snapshot.Tasks.OrderByDescending(t=>t.Cost).Select(t=>{var row=new CostRow(t);return new[]{row.Id,row.Name,row.Cost,row.Actual,row.Remaining,row.Baseline,row.Variance};}));
        html.Append("<h2>Work Overview</h2><p>").Append(E($"Task work: {Total(snapshot.Tasks.Select(t=>t.Work?.Minutes),true)} · Actual work: {Total(snapshot.Tasks.Select(t=>t.ActualWork?.Minutes),true)} · Remaining work: {Total(snapshot.Tasks.Select(t=>t.RemainingWork?.Minutes),true)}")).Append("</p>");HtmlTable(html,["ID","Task","Work","Actual Work","Remaining Work","Baseline Work","Work Variance"],snapshot.Tasks.OrderByDescending(t=>t.Work?.Minutes).Select(t=>{var row=new WorkRow(t);return new[]{row.Id,row.Name,row.Work,row.Actual,row.Remaining,row.Baseline,row.Variance};}));
        html.Append("<h2>Separate Resource Totals</h2>");HtmlTable(html,["Resource","Type","Work","Actual Work","Remaining Work","Cost","Actual Cost","Remaining Cost"],snapshot.Resources.Select(r=>{var row=new ResourceRow(r);return new[]{row.Name,row.Type,row.Work,row.Actual,row.Remaining,row.Cost,row.ActualCost,row.RemainingCost};}));
        var notes=snapshot.Tasks.Where(t=>!string.IsNullOrWhiteSpace(t.Notes)).ToArray();if(notes.Length>0){html.Append("<h2>Task Notes</h2><div class=\"notes\">");HtmlTable(html,["Task","Notes"],notes.Select(t=>new[]{t.Name,t.Notes}));html.Append("</div>");}return html.Append("</body></html>").ToString();}
    private static string E(string? value)=>WebUtility.HtmlEncode(value??"—");
    private static void HtmlTable(StringBuilder html,string[] headings,IEnumerable<string?[]> rows){html.Append("<table><thead><tr>");foreach(var heading in headings)html.Append("<th>").Append(E(heading)).Append("</th>");html.Append("</tr></thead><tbody>");foreach(var row in rows){html.Append("<tr>");foreach(var cell in row)html.Append("<td>").Append(E(cell)).Append("</td>");html.Append("</tr>");}html.Append("</tbody></table>");}
}

